using System.Text.Json;
using System.Text.Json.Nodes;

namespace DotKtX.Experimental.LspSupport;

internal static class WorkspaceWriter
{
    // Keep the original prefix so builds can replace workspaces generated by the projection packages.
    private const string ModulePrefix = "DotKtx.Experimental.LspSupport:";
    private const string LibraryName = "DotKt: CLR KLIBs";
    private const string CompatibilityRoot = "compatibility";
    private const string StampName = ".stamp";
    private static readonly StringComparer PathComparer = OperatingSystem.IsWindows()
        ? StringComparer.OrdinalIgnoreCase
        : StringComparer.Ordinal;

    public static void Generate(
        string projectDirectory,
        string projectName,
        string outputDirectory,
        IReadOnlyList<string> sources,
        IReadOnlyList<string> klibs,
        string sourceList)
    {
        var workspacePath = Path.Combine(projectDirectory, "workspace.json");
        var previousWorkspace = IsOurWorkspace(workspacePath);
        if (File.Exists(workspacePath) && !previousWorkspace)
            throw new InvalidOperationException($"refusing to overwrite existing non-DotKt workspace model '{workspacePath}'");

        var libraries = klibs.Distinct(PathComparer).Order(StringComparer.Ordinal).ToArray();
        foreach (var path in libraries)
        {
            if (!File.Exists(path) && !File.Exists(Path.Combine(path, "default", "manifest")))
                throw new FileNotFoundException($"KLIB does not exist: {path}", path);
        }

        var compatibilityPath = Path.Combine(outputDirectory, CompatibilityRoot);
        var workspace = BuildWorkspace(projectName, compatibilityPath, sources, libraries);

        // The common analyzer still looks up this marker when checking some Kotlin built-in supertypes.
        WriteText(Path.Combine(compatibilityPath, "java", "io", "Serializable.kt"),
            "package java.io\n\ninternal interface Serializable\n");

        var defaultDotKtDirectory = Path.Combine(projectDirectory, ".dotkt");
        if (PathComparer.Equals(Path.GetDirectoryName(outputDirectory), defaultDotKtDirectory))
        {
            var ignorePath = Path.Combine(defaultDotKtDirectory, ".gitignore");
            if (!File.Exists(ignorePath)) WriteText(ignorePath, "*\n");
        }

        WriteText(workspacePath, workspace.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + "\n");

        if (previousWorkspace || File.Exists(Path.Combine(outputDirectory, StampName)))
            RemoveProjection(outputDirectory);

        WriteText(Path.Combine(outputDirectory, StampName), sourceList + "\n", refresh: true);
    }

    public static void Clean(string projectDirectory, string outputDirectory)
    {
        var workspacePath = Path.Combine(projectDirectory, "workspace.json");
        var ownsWorkspace = IsOurWorkspace(workspacePath);
        var stampPath = Path.Combine(outputDirectory, StampName);
        if (ownsWorkspace || File.Exists(stampPath))
        {
            RemoveProjection(outputDirectory);
            DeleteDirectoryIfPresent(Path.Combine(outputDirectory, CompatibilityRoot));
            File.Delete(stampPath);
            if (Directory.Exists(outputDirectory) && !Directory.EnumerateFileSystemEntries(outputDirectory).Any())
                Directory.Delete(outputDirectory);
        }

        if (ownsWorkspace) File.Delete(workspacePath);
    }

    private static void RemoveProjection(string outputDirectory)
    {
        if (!Directory.Exists(outputDirectory)) return;
        DeleteDirectoryIfPresent(Path.Combine(outputDirectory, "stubs"));
        var libraries = Path.Combine(outputDirectory, "libraries");
        if (Directory.Exists(libraries))
        {
            File.Delete(Path.Combine(libraries, "dotkt-klib-java-stubs.jar"));
            if (!Directory.EnumerateFileSystemEntries(libraries).Any()) Directory.Delete(libraries);
        }
        File.Delete(Path.Combine(outputDirectory, "projection-report.md"));
        var readme = Path.Combine(outputDirectory, "README.md");
        if (File.Exists(readme) && File.ReadLines(readme).FirstOrDefault() == "# Generated DotKt LSP model")
            File.Delete(readme);
    }

    private static JsonObject BuildWorkspace(
        string projectName,
        string compatibilityPath,
        IReadOnlyList<string> sources,
        IReadOnlyList<string> klibs)
    {
        var sourceRoots = sources.Where(File.Exists)
            .Select(path => Path.GetDirectoryName(path)!)
            .Append(compatibilityPath)
            .Distinct(PathComparer)
            .Order(StringComparer.Ordinal)
            .ToArray();

        var roots = new JsonArray();
        foreach (var sourceRoot in sourceRoots)
        {
            roots.Add(new JsonObject {
                ["path"] = sourceRoot,
                ["sourceRoots"] = new JsonArray {
                    new JsonObject { ["path"] = sourceRoot, ["type"] = "java-source" },
                },
            });
        }

        // A single library gives the analyzer a common view of the CLR stdlib and reference KLIBs.
        var libraryRoots = new JsonArray();
        foreach (var klib in klibs)
            libraryRoots.Add(new JsonObject { ["path"] = klib });

        var moduleName = ModulePrefix + projectName;
        return new JsonObject {
            ["modules"] = new JsonArray {
                new JsonObject {
                    ["name"] = moduleName,
                    ["dependencies"] = new JsonArray {
                        new JsonObject { ["type"] = "moduleSource" },
                        new JsonObject { ["type"] = "library", ["name"] = LibraryName, ["scope"] = "compile" },
                    },
                    ["contentRoots"] = roots,
                },
            },
            ["libraries"] = new JsonArray {
                new JsonObject { ["name"] = LibraryName, ["type"] = null, ["roots"] = libraryRoots },
            },
            ["kotlinSettings"] = new JsonArray {
                new JsonObject {
                    ["name"] = "Kotlin",
                    ["sourceRoots"] = ToJsonPaths(sourceRoots),
                    ["configFileItems"] = new JsonArray(),
                    ["module"] = moduleName,
                    ["useProjectSettings"] = false,
                    ["implementedModuleNames"] = new JsonArray(),
                    ["dependsOnModuleNames"] = new JsonArray(),
                    ["additionalVisibleModuleNames"] = new JsonArray(),
                    ["productionOutputPath"] = null,
                    ["testOutputPath"] = null,
                    ["sourceSetNames"] = new JsonArray(),
                    ["isTestModule"] = false,
                    ["externalProjectId"] = "",
                    ["isHmppEnabled"] = true,
                    ["pureKotlinSourceFolders"] = ToJsonPaths(sourceRoots),
                    ["kind"] = "source_set_holder",
                    ["compilerArguments"] = "M{\"autoAdvanceLanguageVersion\":false,\"autoAdvanceApiVersion\":false,\"apiVersion\":\"2.4\",\"languageVersion\":\"2.4\",\"companionBlocks\":true,\"companionBlocksAndExtensions\":true}",
                    ["additionalArguments"] = "-Xcompanion-blocks",
                    ["scriptTemplates"] = null,
                    ["scriptTemplatesClasspath"] = null,
                    ["outputDirectoryForJsLibraryFiles"] = null,
                    // This is the combined common platform spelling exported by Kotlin LSP 271.2085.0.
                    ["targetPlatform"] = "JS []/JVM [21]/Native []/Native [general]",
                    ["externalSystemRunTasks"] = new JsonArray(),
                    ["version"] = 5,
                    ["flushNeeded"] = false,
                },
            },
        };
    }

    private static JsonArray ToJsonPaths(IEnumerable<string> paths) =>
        new(paths.Select(path => (JsonNode?)JsonValue.Create(path)).ToArray());

    private static bool IsOurWorkspace(string path)
    {
        if (!File.Exists(path)) return false;
        try
        {
            using var document = JsonDocument.Parse(File.ReadAllText(path));
            return document.RootElement.ValueKind == JsonValueKind.Object &&
                document.RootElement.TryGetProperty("modules", out var modules) &&
                modules.ValueKind == JsonValueKind.Array &&
                modules.GetArrayLength() == 1 &&
                modules.EnumerateArray().All(module =>
                    module.ValueKind == JsonValueKind.Object &&
                    module.TryGetProperty("name", out var name) &&
                    name.ValueKind == JsonValueKind.String &&
                    name.GetString()?.StartsWith(ModulePrefix, StringComparison.Ordinal) == true);
        }
        catch (JsonException)
        {
            return false;
        }
    }

    private static void WriteText(string path, string contents, bool refresh = false)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        if (!refresh && File.Exists(path) && StringComparer.Ordinal.Equals(File.ReadAllText(path), contents)) return;
        var temporary = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
        try
        {
            File.WriteAllText(temporary, contents);
            File.Move(temporary, path, overwrite: true);
        }
        finally
        {
            File.Delete(temporary);
        }
    }

    private static void DeleteDirectoryIfPresent(string path)
    {
        if (Directory.Exists(path)) Directory.Delete(path, recursive: true);
    }
}
